  {de:"gültig", comp:"", sup:"", it:"valido", en:"valid", opp:"ungültig", cat:"aggettivo", ex:[["Ist dein Visum noch gültig?", "Il tuo visto è ancora valido?"]], enex:[["Ist dein Visum noch gültig?", "Is your visa still valid?"]]},
  {de:"überrascht", comp:"überraschter", sup:"am überraschtesten", it:"sorpreso", en:"surprised", opp:"", cat:"aggettivo", prep:"über + Akk. / von + Dat.", ex:[["Als er mich so reden hörte, war er sehr überrascht.", "Quando mi ha sentito parlare così, è rimasto molto sorpreso."]], enex:[["Als er mich so reden hörte, war er sehr überrascht.", "When he heard me talk like that, he was very surprised."]]},
  {de:"günstig", comp:"günstiger", sup:"am günstigsten", it:"conveniente, economico; favorevole", en:"good value, cheap; favourable", opp:"teuer", cat:"aggettivo", ex:[["Sie bietet es den Expats sehr günstig an.", "Lo offre agli expat a un prezzo molto conveniente."]], enex:[["Sie bietet es den Expats sehr günstig an.", "She offers it to the expats at a very good price."]], note:"Più gentile di billig, che può suonare «di bassa qualità».", enNote:"More positive than billig, which can sound «low quality»."},
  {de:"international", comp:"internationaler", sup:"am internationalsten", it:"internazionale", en:"international", opp:"", cat:"aggettivo", ex:[["Die Uni ist sehr international.", "L'università è molto internazionale."]], enex:[["Die Uni ist sehr international.", "The university is very international."]]},
  {de:"gefährlich", comp:"gefährlicher", sup:"am gefährlichsten", it:"pericoloso", en:"dangerous", opp:"ungefährlich", cat:"aggettivo", ex:[["Das ist nicht so gefährlich, wie man denkt.", "Non è così pericoloso come si pensa."]], enex:[["Das ist nicht so gefährlich, wie man denkt.", "It isn't as dangerous as people think."]]},
  {de:"erfolgreich", comp:"erfolgreicher", sup:"am erfolgreichsten", it:"di successo", en:"successful", opp:"erfolglos", cat:"aggettivo", ex:[["Sie ist eine erfolgreiche Unternehmerin.", "È un'imprenditrice di successo."]], enex:[["Sie ist eine erfolgreiche Unternehmerin.", "She is a successful entrepreneur."]], note:"der Erfolg + -reich = con molto successo.", enNote:"der Erfolg + -reich = with a lot of success."},
  {de:"erfolglos", comp:"erfolgloser", sup:"am erfolglosesten", it:"senza successo", en:"unsuccessful", opp:"erfolgreich", cat:"aggettivo", ex:[["Die Suche war leider erfolglos.", "Purtroppo la ricerca non ha avuto successo."]], enex:[["Die Suche war leider erfolglos.", "Unfortunately the search was unsuccessful."]], note:"der Erfolg + -los = senza successo.", enNote:"der Erfolg + -los = without success."},
  {de:"arbeitslos", comp:"", sup:"", it:"disoccupato", en:"unemployed", opp:"berufstätig", cat:"aggettivo", ex:[["Nach dem Studium war er ein halbes Jahr arbeitslos.", "Dopo l'università è stato disoccupato per sei mesi."]], enex:[["Nach dem Studium war er ein halbes Jahr arbeitslos.", "After university he was unemployed for six months."]], note:"die Arbeit + -los. Nome: die Arbeitslosigkeit.", enNote:"die Arbeit + -los. Noun: die Arbeitslosigkeit."},
  {de:"machbar", comp:"", sup:"", it:"fattibile", en:"feasible", opp:"unmöglich", cat:"aggettivo", ex:[["Das Projekt ist machbar, aber nicht einfach.", "Il progetto è fattibile, ma non facile."]], enex:[["Das Projekt ist machbar, aber nicht einfach.", "The project is feasible, but not easy."]], note:"machen + -bar = si può fare.", enNote:"machen + -bar = can be done."},
  {de:"unehrlich", comp:"unehrlicher", sup:"am unehrlichsten", it:"disonesto", en:"dishonest", opp:"ehrlich", cat:"aggettivo", ex:[["Es ist unehrlich, so etwas zu sagen.", "È disonesto dire una cosa del genere."]], enex:[["Es ist unehrlich, so etwas zu sagen.", "It's dishonest to say something like that."]], note:"un- + ehrlich. Nome: die Unehrlichkeit.", enNote:"un- + ehrlich. Noun: die Unehrlichkeit."},
  {de:"desinteressiert", comp:"", sup:"", it:"disinteressato, indifferente", en:"uninterested", opp:"interessiert", cat:"aggettivo", prep:"an + Dat.", ex:[["Die Schüler wirken heute sehr desinteressiert.", "Gli studenti oggi sembrano molto disinteressati."]], enex:[["Die Schüler wirken heute sehr desinteressiert.", "The pupils seem very uninterested today."]], note:"des- + interessiert. Nome: das Desinteresse.", enNote:"des- + interessiert. Noun: das Desinteresse."},
  {de:"inkompetent", comp:"inkompetenter", sup:"am inkompetentesten", it:"incompetente", en:"incompetent", opp:"kompetent", cat:"aggettivo", ex:[["Der neue Chef ist leider völlig inkompetent.", "Il nuovo capo purtroppo è del tutto incompetente."]], enex:[["Der neue Chef ist leider völlig inkompetent.", "Unfortunately the new boss is completely incompetent."]], note:"in- + kompetent. Nome: die Inkompetenz.", enNote:"in- + kompetent. Noun: die Inkompetenz."},
  {de:"betont", comp:"", sup:"", it:"accentato; marcato, ostentato", en:"stressed; pronounced, deliberate", opp:"unbetont", cat:"aggettivo", ex:[["Als Adverb ist eigentlich betont, als Modalpartikel unbetont.", "Come avverbio eigentlich è accentato, come particella no."]], enex:[["Als Adverb ist eigentlich betont, als Modalpartikel unbetont.", "As an adverb eigentlich is stressed, as a particle unstressed."]], note:"Participio di betonen (accentare, sottolineare). In grammatica = con l'accento; in generale anche «ostentato»: betont lässig = ostentatamente disinvolto.", enNote:"Participle of betonen (to stress). In grammar = stressed; generally also «deliberate»: betont lässig = deliberately casual."},
  {de:"unbetont", comp:"", sup:"", it:"non accentato", en:"unstressed", opp:"betont", cat:"aggettivo", ex:[["Modalpartikeln sind immer unbetont.", "Le particelle modali non sono mai accentate."]], enex:[["Modalpartikeln sind immer unbetont.", "Modal particles are always unstressed."]]},
  {de:"fremd", comp:"fremder", sup:"am fremdesten", it:"straniero; estraneo, sconosciuto", en:"foreign; strange, unfamiliar", opp:"vertraut", cat:"aggettivo", ex:[["Am Anfang war mir alles fremd.", "All'inizio tutto mi era estraneo."]], enex:[["Am Anfang war mir alles fremd.", "At first everything was unfamiliar to me."]], note:"Ich bin hier fremd = non sono di qui. die Fremdsprache = lingua straniera.", enNote:"Ich bin hier fremd = I'm not from here. die Fremdsprache = foreign language."},
  {de:"sowieso", comp:"—", sup:"—", it:"comunque, in ogni caso", en:"anyway", opp:"—", cat:"avverbio", ex:[["Am Ende ist sowieso alles anders, als man es geplant hat.", "Alla fine comunque va tutto diversamente da come si era pianificato."]], enex:[["Am Ende ist sowieso alles anders, als man es geplant hat.", "In the end everything turns out differently from what you planned anyway."]]},
  {de:"vorhin", comp:"—", sup:"—", it:"poco fa", en:"a moment ago", opp:"—", cat:"avverbio", ex:[["Ich habe sie vorhin schon telefonieren hören.", "L'ho già sentita telefonare poco fa."]], enex:[["Ich habe sie vorhin schon telefonieren hören.", "I heard her on the phone a moment ago."]], note:"Solo passato recente. ≠ vorher (prima, in precedenza).", enNote:"Only the recent past. ≠ vorher (before, previously)."},
  {de:"gerade", comp:"—", sup:"—", it:"proprio ora; appena", en:"just, right now", opp:"—", cat:"avverbio", ex:[["Ich habe es gerade wegfahren sehen.", "L'ho appena visto partire."]], enex:[["Ich habe es gerade wegfahren sehen.", "I just saw it drive off."]], note:"Con il presente = proprio adesso (Ich esse gerade). Con il passato = appena. Come aggettivo = dritto; gerade Zahl = numero pari.", enNote:"With the present = right now (Ich esse gerade). With the past = just. As an adjective = straight; gerade Zahl = even number."},
  {de:"wohl", comp:"—", sup:"—", it:"probabilmente (supposizione)", en:"probably", opp:"—", cat:"avverbio", ex:[["Sie ist wohl noch zu Hause.", "Sarà ancora a casa."]], enex:[["Sie ist wohl noch zu Hause.", "She's probably still at home."]], note:"Come particella modale esprime una supposizione. Da non confondere con sich wohlfühlen (sentirsi bene).", enNote:"As a modal particle it expresses an assumption. Don't confuse with sich wohlfühlen (to feel good)."},
  {de:"doch", comp:"—", sup:"—", it:"ma sì; eppure; (particella) dai / ma", en:"yes (contradicting); after all; (particle)", opp:"—", cat:"avverbio", ex:[["Hast du keinen Hunger? – Doch!", "Non hai fame? – Sì che ce l'ho!"]], enex:[["Hast du keinen Hunger? – Doch!", "Aren't you hungry? – Yes, I am!"]], note:"Risposta positiva a una domanda negativa. Come particella: rimprovero (Das habe ich doch gesagt!) o invito gentile (Komm doch mit!).", enNote:"Positive answer to a negative question. As a particle: reproach (Das habe ich doch gesagt!) or friendly invitation (Komm doch mit!)."}
