    enRows:[["ich (I)","mich (acc.) · mir (dat.)"],["du (you)","dich · dir"],["er/sie/es (he/she/it)","ihn/sie/es · ihm/ihr/ihm"],["wir (we)","uns · uns"],["ihr (you pl.)","euch · euch"],["Sie (formal you)","Sie · Ihnen"]],
